#!/usr/bin/env bash
# Install the managed shell entrypoint. Safe to run repeatedly.
set -Eeuo pipefail

REPO_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
CONFIG_HOME="${XDG_CONFIG_HOME:-$HOME/.config}"
SHELL_DIR="$CONFIG_HOME/settings"
PROFILE_FILE="$SHELL_DIR/profile.sh"
MARKER_BEGIN="# >>> settings shell >>>"
MARKER_END="# <<< settings shell <<<"

mkdir -p "$SHELL_DIR"
cat > "$PROFILE_FILE" <<EOF
# Generated by settings/install.sh. Keep local-only additions in ~/.config/settings/local.sh.
export SETTINGS_REPO="$REPO_DIR"
[ -r "\$SETTINGS_REPO/shell/profile.sh" ] && . "\$SETTINGS_REPO/shell/profile.sh"
[ -r "\$HOME/.config/settings/local.sh" ] && . "\$HOME/.config/settings/local.sh"
EOF

for shell_profile in "$HOME/.bash_profile" "$HOME/.bashrc"; do
  touch "$shell_profile"
  if ! grep -Fqx "$MARKER_BEGIN" "$shell_profile"; then
    {
      printf '\n%s\n' "$MARKER_BEGIN"
      printf '[ -r "%s" ] && . "%s"\n' "$PROFILE_FILE" "$PROFILE_FILE"
      printf '%s\n' "$MARKER_END"
    } >> "$shell_profile"
  fi
done

manager_config="$CONFIG_HOME/settings-manager"
mkdir -p "$manager_config"
chmod 700 "$manager_config"
if [ ! -e "$manager_config/settings.env" ]; then
  cp "$REPO_DIR/config/settings.env.example" "$manager_config/settings.env"
  chmod 600 "$manager_config/settings.env"
  printf 'Created %s; set a passphrase file before enabling backups.\n' "$manager_config/settings.env"
fi

printf 'Shell setup complete. Open a new Bash shell or run: source "%s"\n' "$PROFILE_FILE"
